// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MelodyToken {
    function owner() external view returns (address);
    function mint(address _to, uint256 _amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d).balanceOf(address(this));

        // Step 1: Get the current owner to verify
        address currentOwner = MelodyToken(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // Step 2: Store attacker address (address(this)) into the owner slot
        // In Ownable contract, _owner is the first (and only) variable, so slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 attackerAsBytes32 = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, attackerAsBytes32);

        // Step 3: Verify we are now the owner
        address newOwner = MelodyToken(TARGET).owner();
        console.log("New owner:", newOwner);
        require(newOwner == attacker, "Failed to become owner");

        // Step 4: Get attacker's initial balance
        uint256 initialBalance = MelodyToken(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Step 5: Mint a large amount of tokens to attacker
        // The total supply is 47,000,000 * 1e18, let's mint 10,000,000 tokens
        uint256 mintAmount = 10_000_000 * 1e18;
        vm.prank(attacker);
        MelodyToken(TARGET).mint(attacker, mintAmount);

        // Step 6: Check final balance
        uint256 finalBalance = MelodyToken(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);

        // Step 7: Verify balance increased
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
        console.log("Exploit successful: Minted", (finalBalance - initialBalance) / 1e18, "MELODY tokens");

        uint256 finalERC20Balance = IERC20(0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
